import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series*')):
 print('\nFILE',f)
 with gzip.open(f,'rt') as h:
  for l in h:
   if l.startswith(('!Series_title','!Series_summary','!Series_overall_design','!Sample_title','!Sample_characteristics','!Sample_treatment_protocol','!Sample_growth_protocol','!Sample_extract_protocol')): print(l[:16000].strip())

