from pypdf import PdfReader
import re
for n in [2,3]:
 print('\nPAPER',n)
 t='\n'.join(p.extract_text() for p in PdfReader(f'studies/papers/paper_{n}.pdf').pages)
 for pat in ['hydroxy','4-O','tamoxifen','RNA','microarray']:
  print('\nPATTERN',pat)
  for m in list(re.finditer(pat,t,re.I)):
   print(t[max(0,m.start()-230):m.end()+450].replace('\n',' '))

